CREATE TABLE auth_state (id INTEGER PRIMARY KEY CHECK(id=1), initialized_at INTEGER, auth_epoch INTEGER NOT NULL DEFAULT 0, canonical_origin TEXT, rp_id TEXT);
INSERT INTO auth_state (id) VALUES (1);
CREATE TABLE owner (id INTEGER PRIMARY KEY CHECK(id=1), created_at INTEGER NOT NULL);
CREATE TABLE admin_keys (purpose TEXT PRIMARY KEY CHECK(purpose IN ('bootstrap','recovery')), secret_display TEXT, secret_digest TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 1, consumed_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE passkeys (id TEXT PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES owner(id), public_key TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, device_type TEXT NOT NULL, backed_up INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE web_sessions (digest TEXT PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES owner(id), auth_epoch INTEGER NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX web_sessions_expiry ON web_sessions(expires_at);
CREATE TABLE webauthn_challenges (id TEXT PRIMARY KEY, challenge TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose IN ('bootstrap','recovery','login','add')), browser_digest TEXT NOT NULL, auth_epoch INTEGER NOT NULL, key_generation INTEGER, canonical_origin TEXT NOT NULL, rp_id TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER);
CREATE INDEX challenge_expiry ON webauthn_challenges(expires_at);
CREATE TABLE auth_operations (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, challenge_id TEXT NOT NULL UNIQUE REFERENCES webauthn_challenges(id), browser_digest TEXT NOT NULL, key_digest TEXT, auth_epoch INTEGER NOT NULL, credential_id TEXT, previous_counter INTEGER, created_at INTEGER NOT NULL);
CREATE TRIGGER guard_auth_operation BEFORE INSERT ON auth_operations BEGIN SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM webauthn_challenges c JOIN auth_state s ON s.id=1 WHERE c.id=NEW.challenge_id AND c.purpose=NEW.purpose AND c.browser_digest=NEW.browser_digest AND c.consumed_at IS NULL AND c.expires_at>NEW.created_at AND c.auth_epoch=NEW.auth_epoch AND s.auth_epoch=NEW.auth_epoch) THEN RAISE(ABORT,'invalid_ceremony') END; SELECT CASE WHEN NEW.purpose IN ('bootstrap','recovery') AND NOT EXISTS (SELECT 1 FROM admin_keys k JOIN webauthn_challenges c ON c.id=NEW.challenge_id WHERE k.purpose=NEW.purpose AND k.secret_digest=NEW.key_digest AND k.consumed_at IS NULL AND k.generation=c.key_generation) THEN RAISE(ABORT,'invalid_admin_key') END; SELECT CASE WHEN NEW.purpose='bootstrap' AND EXISTS (SELECT 1 FROM auth_state WHERE initialized_at IS NOT NULL) THEN RAISE(ABORT,'already_initialized') END; SELECT CASE WHEN NEW.purpose!='bootstrap' AND NOT EXISTS (SELECT 1 FROM auth_state WHERE initialized_at IS NOT NULL) THEN RAISE(ABORT,'not_initialized') END; SELECT CASE WHEN NEW.purpose='login' AND NOT EXISTS (SELECT 1 FROM passkeys WHERE id=NEW.credential_id AND counter=NEW.previous_counter) THEN RAISE(ABORT,'credential_changed') END; END;
